// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // fuzz the boolean that controls whether the helper will revert or succeed
    function testFuzz_property(bool calleeShouldRevert) public {
        // Deploy an adversarial helper that either reverts on call or records the call
        Recorder r = new Recorder(calleeShouldRevert);

        // Call forward and observe whether it returned or reverted
        bool ok;
        try c.forward(address(r), "0x") {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: The reference contract's forward should succeed iff the callee call succeeds.
        // Our helper makes the low-level call succeed when calleeShouldRevert == false, and revert when true.
        // Thus for the reference: ok == (!calleeShouldRevert) for ALL inputs.
        // The mutant flips behavior on success, so it will violate this for some inputs (e.g. when calleeShouldRevert == false)
        assertTrue(ok == (!calleeShouldRevert));
    }
}

// Helper: when shouldRevert==true it always reverts on any call; otherwise it records that it was called and succeeds.
contract Recorder {
    bool public shouldRevert;
    bool public wasCalled;
    bytes public dataReceived;
    uint public valueReceived;

    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }

    fallback() external payable {
        if (shouldRevert) revert("rec revert");
        wasCalled = true;
        dataReceived = msg.data;
        valueReceived = msg.value;
    }

    receive() external payable {
        if (shouldRevert) revert("rec revert");
        wasCalled = true;
        dataReceived = "";
        valueReceived = msg.value;
    }
}
